function renderRoute(){$('routeList').replaceChildren();route.forEach((id,i)=>{const b=bodies.find(b=>b.id===id),row=document.createElement('div');row.className='placeRow';const title=document.createElement('button');title.textContent=(i+1)+'. '+b.name+(routeActive&&i===routeIndex?' · ACTIVE':'');title.onclick=()=>{setTarget(b);closeDialog($('routeDialog'))};const del=document.createElement('button');del.textContent='✕';del.onclick=()=>{route.splice(i,1);routeActive=false;storeRoute();renderRoute()};row.append(title,del);$('routeList').append(row)});$('routeEmpty').hidden=route.length>0;$('startRoute').disabled=route.length===0;$('routeProgress').textContent=routeActive?'ROUTE '+(routeIndex+1)+' / '+route.length:route.length+' planned stops'}
