function routeStep(dt){if(!routeActive)return;if(flight.event?.type==='arrive'){routeDelay=2.5;routeIndex++;flight.event=null;renderRoute()}if(routeDelay>0){routeDelay-=dt;if(routeDelay<=0)nextStop()}}
$('routeBtn').onclick=()=>{renderRoute();open('routeDialog')};$('addStop').onclick=()=>{if(route.length>=8)return toast('Route supports up to eight stops');route.push(selected.id);storeRoute();renderRoute();toast(selected.name+' added to route')};$('startRoute').onclick=()=>{if(surface.active)return toast('Launch and leave the body before starting a route');closeDialog($('routeDialog'));routeActive=true;routeIndex=0;routeDelay=0;nextStop()};$('stopRoute').onclick=()=>{routeActive=false;routeDelay=0;stop();renderRoute()};$('clearRoute').onclick=()=>{routeActive=false;route=[];storeRoute();renderRoute()};

function enterSurface(body,spawn=false){if(body?.landable===false)return toast('This small object has no landing surface. Choose a main asteroid.');if(!spawn)bodyTransition.play('enter',body);shipBoost.selected=false;shipBoost.active=false;boostSelected=false;flight.boostWindow=false;flight.speedCapHeld=0;if(spawn){stableCamera=false;shipCameras.select('chase');shipCameras.valid=false}explorer.cancelOrbit();routeActive=false;surface.enter(body,spawn);explorer.enabled=false;if(spawn){cockpit=false;orbitDistance=16}document.body.classList.toggle('cockpit',cockpit);$('orbitZoom').hidden=!stableCamera;if(!spawn&&stableCamera)camQ.premultiply(new T.Quaternion().setFromRotationMatrix(surfaceFrame(body,surface.normal,bodies))).normalize();else camQ.copy(flight.q);clearInputs();terrain.clear();setTarget(body,true);syncExplorer();updateSurfaceControls();visited.add(body.name);awardDiscovery(body);surfaceView.build();prospecting.key='';prospecting.sync();toast(spawn?body.name+' · launch pad ready':surface.phase==='gas'?body.name+' · gas interior · fly away from the core to exit':body.name+' · airborne entry · you have control; choose Land to descend')}
function launchSurface(){if(surface.requestLaunch()){clearInputs();updateSurfaceControls();updateSurfaceHUD();toast('Launch sequence started · T minus 5 seconds')}else toast('Launch is available while resting on the surface')}
