$('surfaceLaunchBtn').onclick=launchSurface;$('surfaceLandBtn').onclick=()=>navigate('land');$('surfaceAbortBtn').onclick=()=>{if(surface.phase==='countdown'){surface.abort();toast('Countdown cancelled')}else navigate('land')};
