$('tiltEnable').onclick=async()=>{if(tiltEnabled){tiltEnabled=false;tiltOrigin=null;$('tiltEnable').textContent='Enable phone tilt';return}try{if(typeof window.DeviceOrientationEvent==='undefined')return toast('Orientation sensor is unavailable in this browser');if(typeof window.DeviceOrientationEvent.requestPermission==='function'){const result=await window.DeviceOrientationEvent.requestPermission();if(result!=='granted')return toast('Motion permission was not granted')}tiltEnabled=true;tiltOrigin=null;$('tiltEnable').textContent='Disable phone tilt';toast('Tilt enabled · hold the phone comfortably to calibrate')}catch{toast('Motion sensor permission is unavailable')}};
