addEventListener('deviceorientation',e=>{if(!tiltEnabled||!Number.isFinite(e.beta)||!Number.isFinite(e.gamma))return;const angle=(screen.orientation?.angle||0)*Math.PI/180,b=e.beta,g=e.gamma;if(!tiltOrigin){tiltOrigin={b,g};return}const db=b-tiltOrigin.b,dg=g-tiltOrigin.g;tilt.pitch=clamp((db*Math.cos(angle)+dg*Math.sin(angle))/25,-1,1);tilt.roll=clamp((dg*Math.cos(angle)-db*Math.sin(angle))/25,-1,1)});
