function toggleCrew(){sfx.play('equip');if(!surface.active)return toast('Leave ship is available after landing on a world');if(crew.onFoot){if(!crew.board())return toast('Walk within 8 m of your ship to board');toast('Back aboard · ship controls ready')}else{if(!crew.leave())return toast('Land and wait for ground contact before leaving');toast('First person · WASD / left stick walk · drag to look · F board')}clearInputs();document.body.classList.remove('cockpit');cockpit=false;updateSurfaceControls();updateSurfaceHUD()}
