const pinchPointers=new Map();let pinching=false;
canvas.addEventListener('pointerdown',e=>{if(!stableCamera||isBlocked())return;pinchPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinchPointers.size===2){pinching=true;drag=null}});
canvas.addEventListener('pointermove',e=>{const p=pinchPointers.get(e.pointerId);if(!p)return;if(pinchPointers.size===2){const other=[...pinchPointers.entries()].find(([id])=>id!==e.pointerId)[1];zoomOrbit((Math.hypot(p.x-other.x,p.y-other.y)-Math.hypot(e.clientX-other.x,e.clientY-other.y))*3);drag=null}p.x=e.clientX;p.y=e.clientY});
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{pinchPointers.delete(e.pointerId);if(pinching){drag=null;if(pinchPointers.size===1){const [id,p]=pinchPointers.entries().next().value;drag={button:0,id,x:p.x,y:p.y,startX:p.x,startY:p.y};pinching=false}}if(!pinchPointers.size)pinching=false});

addEventListener('blur',()=>{drag=null;pinchPointers.clear();pinching=false});
